-- V3 BLOCK H — INVENTARIO
CREATE TABLE IF NOT EXISTS v3_inventory_suppliers (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,name VARCHAR(190) NOT NULL,tax_id VARCHAR(40) NULL,phone VARCHAR(50) NULL,email VARCHAR(190) NULL,address VARCHAR(255) NULL,notes TEXT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_by INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_v3_supplier_name(name),CONSTRAINT fk_v3_inventory_supplier_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS v3_inventory_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,sku VARCHAR(80) NULL,name VARCHAR(190) NOT NULL,description VARCHAR(1000) NULL,category VARCHAR(100) NULL,unit VARCHAR(30) NOT NULL DEFAULT 'unidad',unit_cost DECIMAL(12,2) NOT NULL DEFAULT 0,min_stock DECIMAL(12,2) NOT NULL DEFAULT 0,stock_quantity DECIMAL(12,2) NOT NULL DEFAULT 0,supplier_id BIGINT UNSIGNED NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_by INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_v3_inventory_sku(sku),KEY idx_v3_inventory_name(name),KEY idx_v3_inventory_category(category),KEY idx_v3_inventory_supplier(supplier_id),CONSTRAINT fk_v3_inventory_item_supplier FOREIGN KEY(supplier_id) REFERENCES v3_inventory_suppliers(id) ON DELETE SET NULL,CONSTRAINT fk_v3_inventory_item_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS v3_inventory_movements (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,item_id BIGINT UNSIGNED NOT NULL,type ENUM('entrada','salida','ajuste') NOT NULL,quantity DECIMAL(12,2) NOT NULL,unit_cost DECIMAL(12,2) NOT NULL DEFAULT 0,reference VARCHAR(120) NULL,notes VARCHAR(1000) NULL,job_id INT NULL,created_by INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_v3_inventory_mov_item(item_id,created_at),KEY idx_v3_inventory_mov_job(job_id),CONSTRAINT fk_v3_inventory_mov_item FOREIGN KEY(item_id) REFERENCES v3_inventory_items(id) ON DELETE CASCADE,CONSTRAINT fk_v3_inventory_mov_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS v3_inventory_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,item_id BIGINT UNSIGNED NULL,actor_user_id INT NULL,event_type VARCHAR(60) NOT NULL,quantity DECIMAL(12,2) NOT NULL DEFAULT 0,metadata JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_v3_inventory_events_item(item_id,created_at),CONSTRAINT fk_v3_inventory_event_item FOREIGN KEY(item_id) REFERENCES v3_inventory_items(id) ON DELETE SET NULL,CONSTRAINT fk_v3_inventory_event_user FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE v3_system ADD COLUMN IF NOT EXISTS inventory_enabled TINYINT(1) NOT NULL DEFAULT 1;